-- Non-ALL compounds run as a merge (multiSelectByMerge): an empty LEFT arm
-- ends EXCEPT / INTERSECT before the right arm starts, so its expressions
-- never evaluate. UNION / UNION ALL always run both arms.
CREATE TABLE a(x INTEGER);
CREATE TABLE b(x INTEGER, f INTEGER);
INSERT INTO b VALUES (1, -9223372036854775808), (2, 2);
SELECT x FROM a EXCEPT SELECT abs(f) FROM b;
SELECT x FROM a INTERSECT SELECT abs(f) FROM b;
SELECT x FROM a UNION SELECT abs(f) FROM b;
SELECT x FROM a UNION ALL SELECT abs(f) FROM b;
SELECT x FROM a EXCEPT SELECT x FROM b WHERE abs(-9223372036854775808);
SELECT x FROM a WHERE x > 0 INTERSECT SELECT x FROM b WHERE abs(f) > 0;
SELECT x FROM a EXCEPT SELECT x FROM b EXCEPT SELECT abs(f) FROM b;
SELECT x FROM b WHERE x = 2 EXCEPT SELECT abs(f) FROM b;
SELECT x FROM b WHERE x = 2 INTERSECT SELECT abs(f) FROM b;
SELECT x FROM b WHERE x > 5 EXCEPT SELECT abs(f) FROM b ORDER BY 1;
SELECT x FROM b WHERE x = 2 EXCEPT SELECT x FROM b WHERE x = 2 EXCEPT SELECT abs(f) FROM b;
INSERT INTO a VALUES (5);
SELECT x FROM a EXCEPT SELECT abs(f) FROM b;
SELECT x FROM a INTERSECT SELECT x FROM b WHERE x > 1;
